import type { JSX } from "react";

/**
 * Refração de borda "Liquid Glass" de verdade (feDisplacementMap, não só blur) pro painel
 * administrativo (/contas) — mesma técnica já usada em src/app/reservas/VidroLiquido.tsx.
 * Renderizado uma vez só aqui (src/app/contas/layout.tsx) porque os 3 filtros valem pra área
 * inteira; cada elemento só referencia o filtro certo no próprio backdrop-filter.
 *
 * Sem a varredura de brilho em loop usada na reserva externa/agendamento — aqui é um painel de
 * trabalho usado o dia todo, não uma experiência de venda, então o efeito fica só na refração
 * (mais discreto) em vez de também animar.
 */
export function DefinicoesDoVidroLiquidoContas(): JSX.Element {
  return (
    <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden="true">
      <defs>
        <filter id="vidro-cartao-contas" colorInterpolationFilters="sRGB" x="0%" y="0%" width="100%" height="100%">
          <feImage result="dispCartaoContas" x="0" y="0" width="420" height="300" preserveAspectRatio="none" href="data:image/png;base64," />
          <feDisplacementMap in="SourceGraphic" in2="dispCartaoContas" scale="-15" xChannelSelector="R" yChannelSelector="G" />
        </filter>
        <filter id="vidro-shell-contas" colorInterpolationFilters="sRGB" x="0%" y="0%" width="100%" height="100%">
          <feImage result="dispShellContas" x="0" y="0" width="500" height="700" preserveAspectRatio="none" href="data:image/png;base64," />
          <feDisplacementMap in="SourceGraphic" in2="dispShellContas" scale="-16" xChannelSelector="R" yChannelSelector="G" />
        </filter>
        <filter id="vidro-abas-contas" colorInterpolationFilters="sRGB" x="0%" y="0%" width="100%" height="100%">
          <feImage result="dispAbasContas" x="0" y="0" width="500" height="50" preserveAspectRatio="none" href="data:image/png;base64," />
          <feDisplacementMap in="SourceGraphic" in2="dispAbasContas" scale="-12" xChannelSelector="R" yChannelSelector="G" />
        </filter>
      </defs>
    </svg>
  );
}
